import { Controller, Get, Req } from '@nestjs/common';
import type { Request } from 'express';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

@Controller('api/v1')
export class FnSfr03201Controller {
  @Get('/hr-records/me')
  async getMyHrRecord(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    return transaction(async (db) => {
      // 임직원은 본인(user.id)의 인사정보만 조회한다
      const rows = await db.query(
        `SELECT e.employee_no AS "employeeNo",
                e.name AS "name",
                h.department_id AS "departmentId",
                h.position_name AS "positionName",
                CAST(h.birth_date AS text) AS "birthDate",
                h.gender AS "gender",
                h.address AS "address",
                h.phone_no AS "phoneNo",
                h.employment_status AS "employmentStatus",
                CAST(h.hire_date AS text) AS "hireDate",
                CAST(h.retirement_date AS text) AS "retirementDate"
           FROM hr_record h
           JOIN employee e ON e.employee_id = h.employee_id
          WHERE h.employee_id = CAST(:userId AS bigint)`,
        { userId: user.id },
      );
      if (rows.length === 0) {
        throw new ApiError(404, 'HR_RECORD_NOT_FOUND', '본인의 인사정보가 없습니다.');
      }
      return rows[0];
    });
  }
}

