import { Badge, DateText, ErrorText, Pairs, RefName, Tiles, call, useData } from '../kit';
import type { PageProps, Row } from '../kit';

export default function FnSfr03201Page({ role, notify }: PageProps) {
  const { data, error, loading } = useData<Row>(
    () => call<Row>('GET', '/hr-records/me', role),
    [role],
  );

  const genderText = (value: unknown) => {
    if (value === 'M') return '남';
    if (value === 'F') return '여';
    return '-';
  };

  const text = (value: unknown) => (value === null || value === undefined || value === '' ? '-' : String(value));

  return (
    <div className="bento">
      <section className="box span-12">
        <h2>재직 현황</h2>
        {error ? <ErrorText text={error} /> : null}
        {loading ? <p>불러오는 중입니다.</p> : null}
        {data ? (
          <Tiles
            items={[
              ['재직 구분', <Badge value={data.employmentStatus} />],
              ['입사일', <DateText value={data.hireDate} />],
              ['직위', text(data.positionName)],
            ]}
          />
        ) : null}
      </section>
      <section className="box span-12">
        <h2>본인 인사정보</h2>
        {data ? (
          <Pairs
            items={[
              ['사번', text(data.employeeNo)],
              ['성명', text(data.name)],
              ['소속 부서', <RefName table="department" role={role} value={data.departmentId} />],
              ['직위', text(data.positionName)],
              ['생년월일', <DateText value={data.birthDate} />],
              ['성별', genderText(data.gender)],
              ['주소', text(data.address)],
              ['연락처', text(data.phoneNo)],
              ['재직 구분', <Badge value={data.employmentStatus} />],
              ['입사일', <DateText value={data.hireDate} />],
              ['퇴직일', <DateText value={data.retirementDate} />],
            ]}
          />
        ) : null}
      </section>
    </div>
  );
}
